<script setup>
import {ref,onMounted} from 'vue'
import {request,upload} from './client'
const props=defineProps({room:Object,role:String}),emit=defineEmits(['completed'])
const result=ref(null),error=ref(''),busy=ref(false),roster=ref(null),page=ref(0)
async function load(){try{if(props.role!=='Student'){roster.value=await request('programme_learning','gradebook',{classroom:props.room.name,page:page.value});return}const state=await request('programme_learning','status',{programme:props.room.programme});result.value=state.modules.find(m=>m.classroom===props.room.name)}catch(e){error.value=e.message}}
async function complete(){busy.value=true;error.value='';try{const state=await request('programme_learning','complete',{classroom:props.room.name});sessionStorage.setItem('sisu-open-programme',state.programme);emit('completed',state.programme)}catch(e){error.value=e.message}finally{busy.value=false}}
async function image(event,kind){const file=event.target.files?.[0];if(!file)return;busy.value=true;error.value='';try{const body=new FormData();body.append('file',file);body.append('kind',kind);body.append('classroom',props.room.name);const saved=await upload('programme_certificates','upload',body);await request('programme_courses','module_image',{classroom:props.room.name,kind,url:saved.url})}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="module-progress panel"><h3>{{role==='Student'?'Your module progress':'Module gradebook'}}</h3><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="result"><p v-if="result.completed">✓ Module completed</p><p v-if="result.grade?.score!=null">Grade: {{result.grade.score}} / 100 <span v-if="result.grade.provisional">· Provisional — awaiting teacher marking</span></p><p v-if="result.grade?.missing_submissions">{{result.grade.missing_submissions}} assessment submission(s) remaining.</p><p>Attendance contributes to your grade but does not block completion.</p><button v-if="!result.completed&&result.allowed&&result.grade?.can_complete" class="button primary" :disabled="busy" @click="complete">Complete module</button></template><div v-if="roster"><details><summary>Module photos</summary><label>Cover photo<input type="file" accept="image/png,image/jpeg" :disabled="busy" @change="image($event,'cover_image')"></label><label>Profile photo<input type="file" accept="image/png,image/jpeg" :disabled="busy" @change="image($event,'profile_image')"></label><p>Photos are saved immediately. Reopen the module to see the updated header.</p></details><p>Assessment marks and your attendance records update these grades automatically.</p><table><thead><tr><th>Student</th><th>Progress</th><th>Grade / 100</th></tr></thead><tbody><tr v-for="row in roster.rows" :key="row.student"><td>{{row.full_name}}</td><td>{{row.completed?'Completed':row.grade.missing_submissions+' submissions remaining'}}</td><td>{{row.grade.score??'Not graded'}}{{row.grade.provisional?' · Provisional':''}}</td></tr></tbody></table><p v-if="!roster.rows.length">No enrolled students yet.</p><div v-if="page||roster.has_more"><button :disabled="!page" @click="page--;load()">Previous</button><button :disabled="!roster.has_more" @click="page++;load()">Next</button></div></div><button class="button subtle" :disabled="busy" @click="load">Refresh progress</button></section></template>
<style scoped>.module-progress{padding:20px;margin:20px 0;overflow-x:auto}.module-progress table{width:100%;border-collapse:collapse}.module-progress th,.module-progress td{text-align:left;padding:10px;border-bottom:1px solid var(--student-border)}.module-progress p{margin:12px 0;line-height:1.6}.module-progress button{margin:8px 12px 0 0}</style>
